    plmn_list = ({ mcc = 222; mnc = 01; mnc_length = 2; snssaiList = ({ sst = 1, sd = 0xffffff }) });

nr_cellid = 12345678L;

////////// Physical parameters:

min_rxtxtime                                              = 6;

servingCellConfigCommon = (
    {
 #spCellConfigCommon

physCellId                                                    = 0;

#  downlinkConfigCommon
    #frequencyInfoDL

# this is 3600 MHz + 43 PRBs@30kHz SCS (same as initial BWP)
      absoluteFrequencySSB                                             = 423130;
      dl_frequencyBand                                                 = 1;

# this is 3600 MHz
      dl_absoluteFrequencyPointA                                       = 422194;
      #scs-SpecificCarrierList
        dl_offstToCarrier                                              = 0;

# subcarrierSpacing

# 0=kHz15, 1=kHz30, 2=kHz60, 3=kHz120
        dl_subcarrierSpacing                                           = 0;
        dl_carrierBandwidth                                            = 52;
     #initialDownlinkBWP
      #genericParameters

# this is RBstart=27,L=48 (275*(L-1))+RBstart
        initialDLBWPlocationAndBandwidth                               = 14025; # 6366 12925 12956 28875 12952

# subcarrierSpacing

# 0=kHz15, 1=kHz30, 2=kHz60, 3=kHz120
        initialDLBWPsubcarrierSpacing                                  = 0;
      #pdcch-ConfigCommon
        initialDLBWPcontrolResourceSetZero                             = 7;
        initialDLBWPsearchSpaceZero                                    = 0;

#uplinkConfigCommon
     #frequencyInfoUL
      ul_frequencyBand                                                 = 1;
      ul_absoluteFrequencyPointA                                       = 384194;
      #scs-SpecificCarrierList
      ul_offstToCarrier                                                = 0;

# subcarrierSpacing

# 0=kHz15, 1=kHz30, 2=kHz60, 3=kHz120
      ul_subcarrierSpacing                                             = 0;
      ul_carrierBandwidth                                              = 52;
      pMax                                                             = 20;
     #initialUplinkBWP
      #genericParameters
        initialULBWPlocationAndBandwidth                               = 14025;

# subcarrierSpacing

# 0=kHz15, 1=kHz30, 2=kHz60, 3=kHz120
        initialULBWPsubcarrierSpacing                                  = 0;
      #rach-ConfigCommon
        #rach-ConfigGeneric
          prach_ConfigurationIndex                                     = 98;
#prach_msg1_FDM
#0 = one, 1=two, 2=four, 3=eight
          prach_msg1_FDM                                               = 0;
          prach_msg1_FrequencyStart                                    = 0;
          zeroCorrelationZoneConfig                                    = 12;
          preambleReceivedTargetPower                                  = -90;
#preamblTransMax (0...10) = (3,4,5,6,7,8,10,20,50,100,200)
          preambleTransMax                                             = 6;
#powerRampingStep

# 0=dB0,1=dB2,2=dB4,3=dB6
        powerRampingStep                                               = 1;
#ssb_perRACH_OccasionAndCB_PreamblesPerSSB_PR
#1=oneeighth,2=onefourth,3=half,4=one,5=two,6=four,7=eight,8=sixteen
        ssb_perRACH_OccasionAndCB_PreamblesPerSSB_PR                   = 4;
#one (0..15) 4,8,12,16,...60,64
        ssb_perRACH_OccasionAndCB_PreamblesPerSSB                      = 15;
#ra_ContentionResolutionTimer
#(0..7) 8,16,24,32,40,48,56,64
        ra_ContentionResolutionTimer                                   = 7;
        rsrp_ThresholdSSB                                              = 19;
#prach-RootSequenceIndex_PR
#1 = 839, 2 = 139
        prach_RootSequenceIndex_PR                                     = 2;
        prach_RootSequenceIndex                                        = 1;

