# pucch-ConfigCommon setup :

# pucchGroupHopping

# 0 = neither, 1= group hopping, 2=sequence hopping
        pucchGroupHopping                                           = 0;
        hoppingId                                                   = 40;
        p0_nominal                                                  = -90;

ssb_PositionsInBurst_Bitmap                                   = 1; #0x80;

# ssb_periodicityServingCell

# 0 = ms5, 1=ms10, 2=ms20, 3=ms40, 4=ms80, 5=ms160, 6=spare2, 7=spare1
      ssb_periodicityServingCell                                    = 2;

# dmrs_TypeA_position

# 0 = pos2, 1 = pos3
      dmrs_TypeA_Position                                           = 0;

# subcarrierSpacing

# 0=kHz15, 1=kHz30, 2=kHz60, 3=kHz120
      subcarrierSpacing                                             = 1;

#tdd-UL-DL-ConfigurationCommon

# subcarrierSpacing

# 0=kHz15, 1=kHz30, 2=kHz60, 3=kHz120
      referenceSubcarrierSpacing                                    = 1;

# pattern1

# dl_UL_TransmissionPeriodicity

# 0=ms0p5, 1=ms0p625, 2=ms1, 3=ms1p25, 4=ms2, 5=ms2p5, 6=ms5, 7=ms10
      dl_UL_TransmissionPeriodicity                                 = 6;
      nrofDownlinkSlots                                             = 7; //8; //7;
      nrofDownlinkSymbols                                           = 6; //0; //6;
      nrofUplinkSlots                                               = 2;
      nrofUplinkSymbols                                             = 4; //0; //4;

ssPBCH_BlockPower                                             = -25;
  }

);

# ------- SCTP definitions
    SCTP :
    {

# Number of streams to use in input/output
        SCTP_INSTREAMS  = 2;
        SCTP_OUTSTREAMS = 2;
    };

////////// MME parameters:

#    mme_ip_address = ({ ipv4 = "192.168.68.130"; port = 36412; });

///X2
    enable_x2         = "yes";
    t_reloc_prep      = 1000;      /* unit: millisecond */
    tx2_reloc_overall = 2000;      /* unit: millisecond */
    t_dc_prep         = 1000;      /* unit: millisecond */
    t_dc_overall      = 2000;      /* unit: millisecond */

target_enb_x2_ip_address = ({ ipv4 = "192.168.68.130"; });

NETWORK_INTERFACES :
    {
      GNB_IPV4_ADDRESS_FOR_S1_MME    = "172.21.16.109";
      GNB_IPV4_ADDRESS_FOR_S1U       = "172.21.16.109";
      GNB_PORT_FOR_S1U               = 2152; # Spec 2152
      GNB_IPV4_ADDRESS_FOR_X2C       = "172.21.16.109";
      GNB_PORT_FOR_X2C               = 36422; # Spec 36422
    };

}
);

MACRLCs = (
  {
    tr_s_preference     = "local_L1";
    tr_n_preference     = "local_RRC";
    pusch_TargetSNRx10  = 200;
    pucch_TargetSNRx10  = 200;
  }
);

L1s = (
{
  tr_n_preference = "local_mac";
  ofdm_offset_divisor = 8; #set this to UINT_MAX for offset 0
}
);

RUs = (
  {
    local_rf       = "yes"
    nb_tx          = 1
    nb_rx          = 1
    att_tx         = 12
    att_rx         = 12;
    bands          = [7];
    max_pdschReferenceSignalPower = -27;
    max_rxgain     = 114;
    eNB_instances  = [0];

#    sdr_addrs = "serial=30C51D4";

#    clock_src      = "external";
  }
);

security = {

# preferred ciphering algorithms

# the first one of the list that an UE supports in chosen

# valid values: nea0, nea1, nea2, nea3
  ciphering_algorithms = ( "nea0" );

# preferred integrity algorithms

# the first one of the list that an UE supports in chosen

# valid values: nia0, nia1, nia2, nia3
  integrity_algorithms = ( "nia2", "nia0" );

# setting 'drb_ciphering' to "no" disables ciphering for DRBs, no matter

# what 'ciphering_algorithms' configures; same thing for 'drb_integrity'
  drb_ciphering = "yes";
  drb_integrity = "no";
};

log_config :
{
  global_log_level      ="info";
  hw_log_level          ="info";
  phy_log_level         ="info";
  mac_log_level         ="info";
  rlc_log_level         ="info";
  pdcp_log_level        ="info";
  rrc_log_level         ="info";
};

uicc: {
  opc = "testopc";
};

